/* ── Static frames ───────────────────────────────────────────────────────── */
function StaticFrame({
  focused = true,
  state = "floating",
  status = "success",
  statusLabel = "Live",
  meta = true,
  controls = "standard",
  size = "md",
  className,
}: {
  focused?: boolean;
  /** Controlled view state, including loading, empty and error states. */
  state?: "tiled" | "floating" | "maximised" | "popout";
  /** Current operation or connection status. */
  status?: WindowStatusTone;
  statusLabel?: string;
  /** Supporting data displayed with the item. */
  meta?: boolean;
  controls?: "standard" | "popout";
  /** Box height: sm (status bar examples), md (states), lg (anatomy). */
  size?: "sm" | "md" | "lg";
  className?: string;
}) {
  const noop = () => {};
  return (
    <div className="gallery-wm-box" data-size={size}>
      <WindowFrame.Root
        focused={focused}
        state={state}
        className={className}
        aria-label="Task manager"
      >
        <WindowFrame.AppBar
          icon={<IconTaskManager />}
          title="Task manager"
          subtitle="NST-C106"
          actions={
            <Button
              variant="ghost"
              size="sm"
              icon={<IconRefresh />}
              aria-label="Refresh processes"
            />
          }
          controls={
            controls === "popout" ? (
              <WindowFrame.Controls title="Task manager" onReturn={noop} onClose={noop} />
            ) : (
              <WindowFrame.Controls
                title="Task manager"
                maximised={state === "maximised"}
                onPopOut={noop}
                onToggleFullscreen={noop}
                onMinimise={noop}
                onToggleMaximise={noop}
                onClose={noop}
              />
            )
          }
        />
        <WindowFrame.Body>
          <ProcessRows />
        </WindowFrame.Body>
        <WindowFrame.StatusBar>
          <WindowFrame.StatusGroup>
            <WindowFrame.StatusItem tone={status}>{statusLabel}</WindowFrame.StatusItem>
            <WindowFrame.StatusItem>142 processes</WindowFrame.StatusItem>
            {meta ? (
              <WindowFrame.StatusMeta>
                <span>CPU 17%</span>
                <span>7.8 GB of 16 GB</span>
              </WindowFrame.StatusMeta>
            ) : null}
          </WindowFrame.StatusGroup>
        </WindowFrame.StatusBar>
      </WindowFrame.Root>
    </div>
  );
}

/* ── Live workspace ──────────────────────────────────────────────────────── */
function MiniWorkspace() {
  // Its own manager: not saved, not synced, no pop-out.
  const [manager] = useState(() =>
    createWindowManager({ storageKey: null, channelName: null, defaultLayout: () => "floating" }),
  );
  const open = (kind: string) => manager.open({ kind, params: { endpoint: "NST-C106" } });
  return (
    <WindowManagerProvider manager={manager}>
      <Toaster />
      <div className="gallery-wm-mini">
        <Workspace
          primaryLabel="NST-C106"
          primary={
            <>
              <EntityHeader
                icon={<IconEndpoint />}
                title="NST-C106"
                subtitle="HP EliteOne 1000 G2 27-in 4K UHD AiO"
                actions={
                  <>
                    <Button icon={<IconTerminal />} onClick={() => open("gallery.terminal")}>
                      Terminal
                    </Button>
                    <Button icon={<IconTaskManager />} onClick={() => open("gallery.processes")}>
                      Task manager
                    </Button>
                    <Button
                      variant="primary"
                      icon={<IconRemoteControl />}
                      onClick={() => open("gallery.screen")}
                    >
                      Connect
                    </Button>
                  </>
                }
              />
              <WindowFrame.Body>
                <Panel>
                  <PanelBody>
                    <p className="fa-hint">
                      Open windows from the header. Drag a title bar to an edge, a corner or the
                      snap bar.
                    </p>
                  </PanelBody>
                </Panel>
              </WindowFrame.Body>
            </>
          }
        />
      </div>
    </WindowManagerProvider>
  );
}

/** A page that is all windows: two tiles fill the stage in a set order; the page shows when both are closed. */
const DASHBOARD_ORDER = ["dashboard-camera", "dashboard-log"];

function DashboardWorkspace() {
  const [manager] = useState(() => {
    const store = createWindowManager({
      storageKey: null,
      channelName: null,
      defaultLayout: () => "tiled",
    });
    // On a phone open windows are sheets over the whole page, so the demo starts closed there.
    if (typeof window !== "undefined" && window.matchMedia(PHONE_QUERY).matches) return store;
    // Opened log first; tileOrder still puts the camera on the left.
    store.open({
      id: "dashboard-log",
      kind: "gallery.gate-log",
      params: { endpoint: "North gate" },
    });
    store.open({
      id: "dashboard-camera",
      kind: "gallery.camera",
      params: { endpoint: "North gate" },
    });
    return store;
  });
  const reopen = () => {
    manager.open({
      id: "dashboard-log",
      kind: "gallery.gate-log",
      params: { endpoint: "North gate" },
    });
    manager.open({
      id: "dashboard-camera",
      kind: "gallery.camera",
      params: { endpoint: "North gate" },
    });
  };
  return (
    <WindowManagerProvider manager={manager}>
      <div className="gallery-wm-mini" data-testid="dashboard-workspace">
        <Workspace
          reservePrimary={false}
          tileOrder={DASHBOARD_ORDER}
          primaryLabel="Front desk"
          primary={
            <WindowFrame.Body>
              <Panel>
                <PanelBody>
                  <p className="fa-hint">The camera and log windows are closed.</p>
                  <Button icon={<IconRemoteControl />} onClick={reopen}>
                    Reopen windows
                  </Button>
                </PanelBody>
              </Panel>
            </WindowFrame.Body>
          }
        />
      </div>
    </WindowManagerProvider>
  );
}

/** A dock with real entries: one focused, one minimised, one popped out. */
function DockSpecimen() {
  const [manager] = useState(() => {
    const store = createWindowManager({
      storageKey: null,
      channelName: null,
      defaultLayout: () => "floating",
    });
    const terminal = store.open({ kind: "gallery.terminal", params: { endpoint: "LMN-4E5E" } });
    store.open({ kind: "gallery.screen", params: { endpoint: "NST-C106" } });
    store.minimise(terminal);
    return store;
  });
  return (
    <WindowManagerProvider manager={manager}>
      <div className="gallery-wm-dock-stage">
        <Dock />
      </div>
    </WindowManagerProvider>
  );
}

